// tables are shared, but these replacement semantics belong to DingTalk's BYO
// AppKey model and deliberately stay out of the shared channel query surface.
// Returns only the requesting Multica member's DingTalk identities. The
// installation list is member-visible, so returning every member's staff id
// here would expose staff ID values more broadly than necessary.
func (q *Queries) ListDingTalkUserBindingsForMember(ctx context.Context, arg ListDingTalkUserBindingsForMemberParams) ([]ListDingTalkUserBindingsForMemberRow, error) {
	rows, err := q.db.Query(ctx, listDingTalkUserBindingsForMember, arg.WorkspaceID, arg.MulticaUserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListDingTalkUserBindingsForMemberRow{}
	for rows.Next() {
		var i ListDingTalkUserBindingsForMemberRow
		if err := rows.Scan(&i.InstallationID, &i.ChannelUserID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockDingTalkDirectOutboundTarget = `-- name: LockDingTalkDirectOutboundTarget :one
WITH installation AS MATERIALIZED (
    SELECT ci.id, ci.workspace_id, ci.agent_id, ci.channel_type, ci.config, ci.status, ci.ws_lease_token, ci.ws_lease_expires_at, ci.installer_user_id, ci.installed_at, ci.created_at, ci.updated_at, ci.target_type, ci.target_id
    FROM channel_installation ci
    WHERE ci.id = $1
      AND ci.workspace_id = $2
      AND ci.channel_type = 'dingtalk'
      AND ci.status = 'active'
      AND COALESCE(ci.target_type, 'agent') = $3::text
      AND COALESCE(ci.target_id, ci.agent_id) = $4
    FOR SHARE OF ci
), target_agent AS MATERIALIZED (
    SELECT a.id
    FROM installation i
    JOIN agent a ON a.id = COALESCE(i.target_id, i.agent_id)
                AND a.workspace_id = i.workspace_id
    WHERE COALESCE(i.target_type, 'agent') = 'agent'
      AND a.id = $5
      AND a.kind = 'user'
      AND a.archived_at IS NULL
    FOR SHARE OF a
), target_squad AS MATERIALIZED (
    SELECT a.id
    FROM installation i
    JOIN squad s ON s.id = i.target_id AND s.workspace_id = i.workspace_id
    JOIN agent a ON a.id = s.leader_id AND a.workspace_id = s.workspace_id
    WHERE i.target_type = 'squad'
      AND a.id = $5
      AND s.leader_revision = $6
      AND s.archived_at IS NULL
      AND a.kind = 'user'
      AND a.archived_at IS NULL
    FOR SHARE OF s, a
)
SELECT id FROM target_agent
UNION ALL
SELECT id FROM target_squad
`

